-- Guest Hub — never a silent staff send (15 Nov 2026, Ahmed, found 18:20 Riyadh: «إرسال تجربة لي» did nothing and showed
-- nothing; hub_templates had last been refreshed on 13 Nov, so hub_daily_report and hub_staff_alert — approved by Meta on
-- 15 Nov — were refused as «template_unread», and the staff alerts with them). Generated by scripts/hub-send-migration.mjs
-- — never edited once applied (CLAUDE.md §12).
--   1. Any refused or failed staff send (an alert, an escalation, a report, a test report) opens or counts on ONE alert per
--      unit, «رسالة للفريق لم تُرسل» (hub_alerts staff_send: the count, the last reason, the template), shown in the
--      dashboard's alerts area, and counts in the daily report's «أعطال» (staff_refused).
--   2. «إرسال تجربة لي» returns the send's id; hub_staff_send_status lets the dashboard wait for the real outcome.
--   3. hub_templates_due: the channels whose hub templates are missing, not APPROVED or older than a day — wa-automation's
--      minute drain reads them again from YCloud (once a day each, and right before a send when needed).
-- No unit mode, licence or switch changes. No phone number in this file.

alter table public.hub_alerts drop constraint hub_alerts_kind_check;
alter table public.hub_alerts add constraint hub_alerts_kind_check
  check (kind in ('budget_pct', 'budget_cap', 'portfolio_pct', 'quality_drop', 'offer_ending', 'card_expiring', 'spike', 'escalation', 'complaint',
                  'webhook_silent', 'template_rejected', 'api_credit', 'flagged_wrong', 'model_error', 'voice_cap', 'staff_send'));

-- public.hub_report_test (20261115200000, copied): the send's id
create or replace function public.hub_report_test() returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  r public.hub_report_recipients;
  v_send uuid;
  v_mine boolean := true;
  v_channel uuid := internal.hub_branch_channel('airport-road');
  v_day date := (now() at time zone 'Asia/Riyadh')::date;
begin
  if not internal.is_system_admin() then raise exception 'forbidden' using errcode = '42501'; end if;
  select * into r from public.hub_report_recipients x where x.staff_user_id = auth.uid() order by x.position limit 1;
  if r.id is null then
    v_mine := false;
    select * into r from public.hub_report_recipients x order by x.position limit 1;
  end if;
  if r.id is null then raise exception 'hub_report_no_recipient' using errcode = '22023'; end if;
  if v_channel is null then raise exception 'hub_report_no_channel' using errcode = '22023'; end if;
  if exists (select 1 from public.hub_staff_sends s where s.kind = 'report_test' and s.created_at > now() - interval '1 minute') then
    raise exception 'hub_report_test_wait' using errcode = '22023';
  end if;
  insert into public.hub_staff_sends (kind, report_day, recipient_id, channel_id, template, payload)
  values ('report_test', v_day, r.id, v_channel, 'hub_daily_report', internal.hub_report_data(v_day, now())) returning id into v_send;
  perform internal.hub_kick_staff_sender();
  -- the dashboard waits for the real outcome through hub_staff_send_status (never «أُرسل» before it is)
  return jsonb_build_object('ok', true, 'recipient', r.name, 'mine', v_mine, 'send_id', v_send);
end;
$$;

-- public.hub_staff_send_finish (20261115200000, copied): a refused or failed send → the staff_send alert
create or replace function public.hub_staff_send_finish(p_send uuid, p_status text, p_provider_id text, p_error_code text) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  s public.hub_staff_sends;
  v_unit uuid;
begin
  if p_status not in ('accepted', 'sent', 'delivered', 'read', 'failed', 'test', 'skipped') then raise exception 'hub_staff_send_finish' using errcode = '22023'; end if;
  update public.hub_staff_sends
     set status = p_status, provider_message_id = coalesce(nullif(left(p_provider_id, 200), ''), provider_message_id),
         error_code = case when p_status in ('failed', 'skipped') then coalesce(nullif(left(p_error_code, 40), ''), p_status) end, updated_at = now()
   where id = p_send and status = 'pending'
  returning * into s;
  if s.id is null then return jsonb_build_object('ok', false); end if;
  -- never silent (Ahmed, 15 Nov 2026): a refused or failed send opens or counts on ONE alert of the unit of its number
  if s.status in ('failed', 'skipped') and coalesce(s.error_code, '') <> 'qa' and not s.is_test then
    select c.unit_id into v_unit from public.hub_channels c where c.id = s.channel_id;
    update public.hub_alerts a
       set payload = a.payload || jsonb_build_object('count', coalesce((a.payload ->> 'count')::int, 0) + 1, 'last_code', s.error_code, 'template', s.template,
                                                     'last_kind', s.kind, 'last_at', now())
     where a.kind = 'staff_send' and a.unit_id is not distinct from v_unit and a.acknowledged_at is null and not a.is_test;
    if not found then
      insert into public.hub_alerts (kind, unit_id, payload)
      values ('staff_send', v_unit, jsonb_build_object('count', 1, 'last_code', s.error_code, 'template', s.template, 'last_kind', s.kind, 'last_at', now()))
      on conflict do nothing;
    end if;
  end if;
  return jsonb_build_object('ok', true, 'status', s.status, 'error_code', s.error_code);
end;
$$;

-- internal.hub_report_data (20261115400000, copied): staff_refused per branch
create or replace function internal.hub_report_data(p_day date, p_to timestamptz default null) returns jsonb
language plpgsql stable security definer set search_path = '' as $$
declare
  v_from timestamptz := (p_day::timestamp at time zone 'Asia/Riyadh');
  v_to timestamptz := coalesce(p_to, ((p_day + 1)::timestamp at time zone 'Asia/Riyadh'));
  v_branches jsonb := '{}'::jsonb;
  b text;
  v jsonb;
begin
  foreach b in array array['airport-road', 'shafa-road'] loop
    with conv as (
           select distinct c.id from public.hub_conversations c join public.hub_units u on u.id = c.unit_id join public.hub_messages m on m.conversation_id = c.id
            where u.branch_slug = b and not c.is_test and m.direction = 'in' and m.author = 'guest' and m.sent_at >= v_from and m.sent_at < v_to),
         ho as (select h.* from public.hub_handoffs h where h.branch_slug = b and not h.is_test and h.created_at >= v_from and h.created_at < v_to),
         sends as (select s.* from public.hub_staff_sends s join ho on ho.id = s.handoff_id)
    select jsonb_build_object(
      'conversations', (select count(*) from conv),
      'handed', (select count(distinct ho.conversation_id) from ho),
      'assistant', (select count(*) from conv where not exists (select 1 from ho where ho.conversation_id = conv.id)
                       and exists (select 1 from public.hub_messages m where m.conversation_id = conv.id and m.author = 'assistant' and m.direction = 'out'
                                     and m.status in ('accepted', 'sent', 'delivered', 'read') and m.sent_at >= v_from and m.sent_at < v_to)),
      'reply_avg_min', (select round(avg(extract(epoch from (ho.first_reply_at - ho.created_at)) / 60.0))::integer from ho where ho.first_reply_at is not null),
      'replied', (select count(*) from ho where ho.first_reply_at is not null),
      'bookings', (select count(*) from public.reservations r where r.branch = b and r.booking_source = 'assistant_whatsapp' and not r.is_test
                     and r.created_at >= v_from and r.created_at < v_to),
      'reviews', (select count(*) from public.whatsapp_messages w where w.branch = b and w.template = 'stay_review' and not w.is_test
                    and w.status in ('accepted', 'sent', 'delivered', 'read') and w.created_at >= v_from and w.created_at < v_to),
      'unanswered', (select count(*) from public.hub_unanswered q join public.hub_units u on u.id = q.unit_id
                       where u.branch_slug = b and not q.is_test and q.created_at >= v_from and q.created_at < v_to),
      'model_failures', (select count(*) from public.hub_turns t join public.hub_units u on u.id = t.unit_id
                           where u.branch_slug = b and not t.is_test and t.status = 'failed' and t.created_at >= v_from and t.created_at < v_to),
      'send_failures', (select count(*) from public.hub_messages m join public.hub_conversations c on c.id = m.conversation_id join public.hub_units u on u.id = c.unit_id
                          where u.branch_slug = b and not c.is_test and m.direction = 'out' and m.status = 'failed' and m.created_at >= v_from and m.created_at < v_to)
                       + (select count(*) from sends where sends.status = 'failed'),
      -- H7: the voice notes and images that failed (never a cap: it has its own email)
      'voice_failures', (select count(*) from public.hub_messages m join public.hub_conversations c on c.id = m.conversation_id join public.hub_units u on u.id = c.unit_id
                           where u.branch_slug = b and not c.is_test and m.direction = 'in' and m.kind = 'audio'
                             and m.media_status in ('failed_download', 'failed_transcribe', 'empty', 'unknown_language') and m.created_at >= v_from and m.created_at < v_to),
      'image_failures', (select count(*) from public.hub_messages m join public.hub_conversations c on c.id = m.conversation_id join public.hub_units u on u.id = c.unit_id
                           where u.branch_slug = b and not c.is_test and m.direction = 'in' and m.kind = 'image'
                             and m.media_status in ('failed_download', 'failed_vision') and m.created_at >= v_from and m.created_at < v_to),
      -- 15 Nov 2026: the staff alerts of the branch's hand-offs refused or failed (never silent)
      'staff_refused', (select count(*) from sends where sends.status in ('failed', 'skipped') and coalesce(sends.error_code, '') <> 'qa'),
      'alerts_sent', (select count(*) from sends where sends.status in ('accepted', 'sent', 'delivered', 'read')),
      'alerts_delivered', (select count(*) from sends where sends.status in ('delivered', 'read')),
      'alerts_read', (select count(*) from sends where sends.status = 'read'),
      'escalated', (select count(*) from ho where ho.escalated_at is not null),
      'opened', (select count(*) from ho where ho.opened_at is not null),
      'opened_link', (select count(*) from ho where ho.opened_via = 'link'),
      'email_only', (select count(*) from ho where ho.status = 'email_only'),
      'reasons', (select coalesce(jsonb_object_agg(z.reason, z.n), '{}'::jsonb) from (select coalesce(ho.reason, 'handoff') as reason, count(*) as n from ho group by 1) z)
    ) into v;
    v_branches := v_branches || jsonb_build_object(b, v);
  end loop;
  return jsonb_build_object('day', p_day, 'partial', p_to is not null, 'until', v_to, 'branches', v_branches,
    -- the daily and test reports refused or failed (they belong to no hand-off)
    'reports_refused', (select count(*) from public.hub_staff_sends s where s.kind in ('report', 'report_test') and s.status in ('failed', 'skipped')
                          and coalesce(s.error_code, '') <> 'qa' and not s.is_test and s.created_at >= v_from and s.created_at < v_to),
    'cards', (select count(*) from public.hub_knowledge_cards k where not k.is_test and k.published_at >= v_from and k.published_at < v_to),
    'budget_alerts', (select count(*) from public.hub_alerts a where a.kind in ('budget_pct', 'budget_cap', 'api_credit') and not a.is_test and a.created_at >= v_from and a.created_at < v_to),
    'built_at', now());
end;
$$;

-- a staff send's outcome, for «إرسال تجربة لي» (the system admin) and «الفريق والتقارير» (hub_team view): codes only
create function public.hub_staff_send_status(p_send uuid) returns jsonb
language plpgsql stable security definer set search_path = '' as $$
declare s public.hub_staff_sends;
begin
  if not internal.is_system_admin() and not internal.can('hub_team', 'view') then raise exception 'forbidden' using errcode = '42501'; end if;
  select * into s from public.hub_staff_sends where id = p_send;
  if s.id is null then raise exception 'not_found' using errcode = '22023'; end if;
  return jsonb_build_object('id', s.id, 'kind', s.kind, 'template', s.template, 'status', s.status, 'error_code', s.error_code, 'updated_at', s.updated_at);
end;
$$;

-- the channels whose hub templates must be read again from YCloud: a hub template missing, not APPROVED, without a body, or
-- read more than a day ago (service role — wa-automation's minute drain)
create function public.hub_templates_due() returns jsonb
language sql stable security definer set search_path = '' as $$
  select coalesce(jsonb_agg(jsonb_build_object('channel_id', c.id, 'waba_id', c.waba_id)), '[]'::jsonb)
    from public.hub_channels c
   where c.waba_id is not null and c.verified_at is not null
     and exists (select 1 from (values ('hub_staff_alert', 'ar'), ('hub_daily_report', 'ar'), ('hub_reply_ready', 'ar')) w(name, language)
                  where not exists (select 1 from public.hub_templates t where t.channel_id = c.id and t.name = w.name and t.language = w.language
                                      and t.status = 'APPROVED' and t.body is not null and t.read_at > now() - interval '1 day'))
$$;

revoke execute on function public.hub_staff_send_status(uuid) from public, anon;
grant execute on function public.hub_staff_send_status(uuid) to authenticated;
revoke execute on function public.hub_templates_due() from public, anon, authenticated;
grant execute on function public.hub_templates_due() to service_role;
